code.source:
#include <stdio.h>

int square(int n) {
    int result = n * n;
    return result;
}

float average(int a, int b) {
    return (a + b) / 2.0f;
}

int main(void) {
    int s = square(7);
    printf("7 squared is %d\n", s);
    printf("Average of 4 and 7 is %.1f\n", average(4, 7));
    printf("Square of square(3) is %d\n", square(square(3)));
    return 0;
}

